//! Integration test: the engine loads and queries P1's real H3 grid
//! (`data/nasa-layers/hexgrid_route_res12_hexcell64b.parquet`, generated by
//! `cd data/pipeline && uv run python -m red_atlas_p1.hexgrid`).
//!
//! Node positions and leg lengths are read from P1's GeoJSON
//! (`data/mission-scenarios/triangulo_supervivencia.geojson`), not from `red_atlas_shared`.

use std::collections::HashMap;
use std::path::PathBuf;
use std::time::Instant;

use red_atlas_core::h3_mars_grid::{
    geodesic_distance_m, h3_resolution, lat_lon_to_h3, H3MarsGrid, HAZARD_FLAG_ISRU_WATER,
    HAZARD_FLAG_NLOS, HAZARD_FLAG_REGOLITH_TRAP, HAZARD_FLAG_SHELTER,
};
use red_atlas_core::metabolic_dstar::{CostWeights, MetabolicDStarPlanner};
use red_atlas_shared::{
    is_no_data, ActiveHazards, DUST_TAU_STORM, NLOS_RSSI_THRESHOLD_DBM, SPE_PEAK_ENVELOPE_MSV_H,
};

fn repo_path(rel: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..").join(rel)
}

fn load_res12() -> H3MarsGrid {
    let path = repo_path("data/nasa-layers/hexgrid_route_res12_hexcell64b.parquet");
    H3MarsGrid::load_p1_parquet(&path)
        .unwrap_or_else(|e| panic!("cannot load P1 grid {}: {e}", path.display()))
}

struct Geo {
    /// node_id -> (lat_deg, lon_east_deg)
    nodes: HashMap<String, (f64, f64)>,
    /// (leg_id, from, to, distance_m)
    legs: Vec<(String, String, String, f64)>,
}

fn load_geojson() -> Geo {
    let path = repo_path("data/mission-scenarios/triangulo_supervivencia.geojson");
    let text = std::fs::read_to_string(&path).expect("GeoJSON readable");
    let doc: serde_json::Value = serde_json::from_str(&text).expect("valid GeoJSON");
    let mut nodes = HashMap::new();
    let mut legs = Vec::new();
    for f in doc["features"].as_array().expect("features") {
        let props = &f["properties"];
        match f["geometry"]["type"].as_str() {
            // GeoJSON order: [lon_E 0-360, lat, elev]
            Some("Point") => {
                let c = &f["geometry"]["coordinates"];
                nodes.insert(
                    props["node_id"].as_str().unwrap().to_string(),
                    (c[1].as_f64().unwrap(), c[0].as_f64().unwrap()),
                );
            }
            Some("LineString") => legs.push((
                props["leg_id"].as_str().unwrap().to_string(),
                props["from"].as_str().unwrap().to_string(),
                props["to"].as_str().unwrap().to_string(),
                props["distance_m"].as_f64().unwrap(),
            )),
            _ => {}
        }
    }
    Geo { nodes, legs }
}

#[test]
fn p1_res12_grid_matches_survival_triangle() {
    let t0 = Instant::now();
    let grid = load_res12();
    let load_ms = t0.elapsed().as_secs_f64() * 1e3;
    println!("Loaded {} P1 cells at res {} in {load_ms:.0} ms", grid.len(), grid.res);

    // SCHEMA_HEXGRID.md §1 and §6.
    assert_eq!(grid.res, 12);
    assert_eq!(grid.len(), 141_313);
    assert!(grid.all_cells().all(|c| c.verify_crc() && h3_resolution(c.h3_index) == Some(12)));
    let tiu_null = grid.all_cells().filter(|c| is_no_data(c.thermal_inertia_tiu)).count();
    let h2o_null = grid.all_cells().filter(|c| is_no_data(c.isru_h2o_pct)).count();
    assert_eq!(tiu_null, 139_978, "P1 NULL TIU must load as CELL_NO_DATA, not 0");
    assert_eq!(h2o_null, 141_020);
    assert!(grid.all_cells().all(|c| is_no_data(c.roughness_hi)));
    assert!(grid.all_cells().all(|c| c.los_base_rssi_dbm.is_finite()));

    let geo = load_geojson();
    assert_eq!(geo.nodes.len(), 4);

    // Node cells (SCHEMA_HEXGRID.md §7, computed by the Python `h3` library).
    let expected: [(&str, u64, u16); 4] = [
        ("BASE", 0x8c8f591152cb1ff, 0x00),
        ("WP1", 0x8c8f5911c103dff, 0x10),
        ("WP2", 0x8c8f5911eaabdff, 0x0a),
        ("WP3", 0x8c8f5911e823bff, 0x0d),
    ];
    let mut node_cell = HashMap::new();
    for (id, h3, flags) in expected {
        let (lat, lon) = geo.nodes[id];
        assert_eq!(lat_lon_to_h3(lat, lon, 12), h3, "{id} index");
        let cell = grid.nearest_cell(lat, lon).expect("node cell");
        assert_eq!(cell.h3_index, h3, "{id}: node must fall inside a loaded cell");
        assert_eq!(cell.hazard_bitmask, flags, "{id} flags");
        node_cell.insert(id.to_string(), cell.h3_index);
    }
    let wp1 = grid.get_cell(node_cell["WP1"]).unwrap();
    assert!((wp1.isru_h2o_pct - 12.0).abs() < 1e-4 && wp1.hazard_bitmask & HAZARD_FLAG_ISRU_WATER != 0);
    let wp2 = grid.get_cell(node_cell["WP2"]).unwrap();
    assert!(wp2.hazard_bitmask & HAZARD_FLAG_REGOLITH_TRAP != 0);
    assert!(wp2.los_base_rssi_dbm < NLOS_RSSI_THRESHOLD_DBM && wp2.hazard_bitmask & HAZARD_FLAG_NLOS != 0);
    let wp3 = grid.get_cell(node_cell["WP3"]).unwrap();
    assert!((wp3.sky_view_factor - 0.15).abs() < 1e-4 && wp3.hazard_bitmask & HAZARD_FLAG_SHELTER != 0);

    // "Within one cell": the largest center-to-center distance between the Base cell and its
    // neighbors in the loaded grid (≈ √3 × local edge). Fixed before comparing the legs.
    let one_cell_m = grid
        .neighbor_edges(node_cell["BASE"])
        .iter()
        .map(|&(_, d)| d)
        .fold(0.0, f64::max);
    assert!(one_cell_m > 9.0 && one_cell_m < 12.0, "cell spacing {one_cell_m} m");

    let mut checked = 0;
    for (leg, from, to, distance_m) in &geo.legs {
        let d = geodesic_distance_m(node_cell[from], node_cell[to]);
        println!("{leg} {from}->{to}: cells {d:.1} m, GeoJSON {distance_m:.0} m (tol {one_cell_m:.1} m)");
        assert!(
            (d - distance_m).abs() <= one_cell_m,
            "{leg}: {d:.1} m vs {distance_m} m exceeds one cell ({one_cell_m:.1} m)"
        );
        if ["L1", "L2", "L3", "L4"].contains(&leg.as_str()) {
            checked += 1;
        }
    }
    assert_eq!(checked, 4, "the four triangle legs must be in the GeoJSON");

    // Spyglass on real cells: 100 m ≈ k 10 around WP1.
    let slice = grid.query_spyglass_sectors(node_cell["WP1"], 10);
    assert_eq!(slice.crism_water_cells.len(), 331);
}

/// Planner on the real terrain (reported, with loose sanity asserts). Run with `--nocapture`
/// to see the timings.
#[test]
fn p1_res12_grid_supports_dstar_escape() {
    let grid = load_res12();
    let geo = load_geojson();
    let cell_of = |id: &str| {
        let (lat, lon) = geo.nodes[id];
        grid.nearest_cell(lat, lon).unwrap().h3_index
    };
    let (wp2, wp3, base) = (cell_of("WP2"), cell_of("WP3"), cell_of("BASE"));

    let t0 = Instant::now();
    let (cells, adj) = grid.planner_graph();
    let graph_ms = t0.elapsed().as_secs_f64() * 1e3;
    let mut planner = MetabolicDStarPlanner::new(cells, adj);

    // T+105 hazards as in eva07_mission_sim.
    let hazards = ActiveHazards {
        h1_dust_storm: true,
        h2_spe_radiation: true,
        h3_regolith_slope: true,
        h4_nlos_offline: true,
        dust_tau: DUST_TAU_STORM,
        wind_speed_ms: 28.0,
        spe_dose_rate_msv_h: SPE_PEAK_ENVELOPE_MSV_H,
        rssi_dbm: grid.get_cell(wp2).unwrap().los_base_rssi_dbm,
    };
    let weights = CostWeights::default();

    for (label, goal, straight_m) in [("WP2->WP3", wp3, 595.4), ("WP2->Base", base, 2148.2)] {
        let t = Instant::now();
        let path = planner
            .plan_path(wp2, goal, &hazards, &weights)
            .unwrap_or_else(|| panic!("{label}: no path on the real grid"));
        let ms = t.elapsed().as_secs_f64() * 1e3;
        let len_m: f64 = path
            .path_h3
            .windows(2)
            .map(|w| geodesic_distance_m(w[0], w[1]))
            .sum();
        println!(
            "{label}: {} cells, {len_m:.0} m along the grid ({straight_m} m straight), {:.1} min, \
             {:.2} L O2, {:.3} mSv, planned in {ms:.0} ms (graph {graph_ms:.0} ms)",
            path.path_h3.len(),
            path.estimated_time_min,
            path.estimated_o2_liters,
            path.estimated_rad_msv,
        );
        assert!(path.estimated_time_min.is_finite() && path.total_cost.is_finite());
        assert!(len_m >= straight_m - 11.0, "{label}: path shorter than the straight line");
    }
}

/// Diagnostic only (`--ignored --nocapture`): edge slope statistics of the res-12 graph.
#[test]
#[ignore]
fn p1_res12_edge_slope_diagnostic() {
    let grid = load_res12();
    let (cells, adj) = grid.planner_graph();
    let (mut total, mut flat, mut over30, mut over30_cells_ok, mut nlos_rssi_ok, mut nlos) =
        (0usize, 0usize, 0usize, 0usize, 0usize, 0usize);
    for (i, a) in adj.iter().enumerate() {
        for &(j, d) in a {
            let (u, v) = (&cells[i], &cells[j]);
            if is_no_data(u.elev_m) || is_no_data(v.elev_m) {
                continue;
            }
            total += 1;
            let dz = (v.elev_m - u.elev_m) as f64;
            if dz.abs() < 1e-3 {
                flat += 1;
            }
            let g = (dz / d).atan().to_degrees().abs();
            if g > 30.0 {
                over30 += 1;
                if u.slope_deg <= 30.0 && v.slope_deg <= 30.0 {
                    over30_cells_ok += 1;
                }
            }
        }
    }
    for c in grid.all_cells() {
        if c.hazard_bitmask & HAZARD_FLAG_NLOS != 0 {
            nlos += 1;
            if c.los_base_rssi_dbm >= NLOS_RSSI_THRESHOLD_DBM {
                nlos_rssi_ok += 1;
            }
        }
    }
    println!(
        "edges {total}, dz=0 {flat} ({:.1}%), geom>30deg {over30} of which both cells <=30deg {over30_cells_ok}; \
         NLOS cells {nlos}, with filled RSSI >= -100 dBm {nlos_rssi_ok}",
        100.0 * flat as f64 / total as f64
    );
}
